using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Win32.SafeHandles;

// Private fixed-helper transport for bytes generated by the bounded text-PDF
// recipe. This class supplies no authentication, generic binary-write tool,
// filesystem discovery, overwrite, cleanup, retry or installed-runtime authority.
// Creation and every byte operation use one retained native output handle.
public sealed class SovereignPdfWriteV1 : IDisposable {
    public const int MaxPdfBytes = 65536, MaxPages = 8, MaxRunMs = 5000;
    const uint Read = 0x00120089, ShareRead = 1;
    const int NameMissing = unchecked((int)0xc0000034);

    [StructLayout(LayoutKind.Sequential)] struct UnicodeString {
        public ushort Length, MaximumLength; public IntPtr Buffer;
    }
    [StructLayout(LayoutKind.Sequential)] struct ObjectAttributes {
        public int Length; public IntPtr RootDirectory, ObjectName;
        public uint Attributes; public IntPtr SecurityDescriptor, SecurityQualityOfService;
    }
    [StructLayout(LayoutKind.Sequential)] struct IoStatusBlock {
        public IntPtr Status; public UIntPtr Information;
    }
    [StructLayout(LayoutKind.Sequential)] struct FileInformation {
        public uint Attributes;
        public System.Runtime.InteropServices.ComTypes.FILETIME Creation, Access, Write;
        public uint Volume, SizeHigh, SizeLow, Links, IndexHigh, IndexLow;
    }
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
    static extern SafeFileHandle CreateFileW(string name, uint access, uint share,
        IntPtr security, uint creation, uint flags, IntPtr template);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool GetFileInformationByHandle(SafeFileHandle handle, out FileInformation info);
    [DllImport("kernel32.dll", SetLastError=true)] static extern uint GetFileType(SafeFileHandle handle);
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode)] static extern uint GetDriveTypeW(string root);
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
    static extern uint GetFinalPathNameByHandleW(SafeFileHandle handle, StringBuilder path, uint size, uint flags);
    [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
    static extern bool GetVolumeInformationByHandleW(SafeFileHandle root, StringBuilder label, uint labelSize,
        out uint serial, out uint maxName, out uint flags, StringBuilder filesystem, uint filesystemSize);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool SetFilePointerEx(SafeFileHandle handle, long distance, out long position, uint method);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool ReadFile(SafeFileHandle handle, byte[] buffer, uint count, out uint read, IntPtr overlapped);
    [DllImport("kernel32.dll", SetLastError=true)]
    static extern bool WriteFile(SafeFileHandle handle, byte[] buffer, uint count, out uint written, IntPtr overlapped);
    [DllImport("kernel32.dll", SetLastError=true)] static extern bool FlushFileBuffers(SafeFileHandle handle);
    [DllImport("ntdll.dll")]
    static extern int NtCreateFile(out IntPtr handle, uint access, ref ObjectAttributes attributes,
        out IoStatusBlock status, IntPtr size, uint fileAttributes, uint sharing,
        uint disposition, uint options, IntPtr ea, uint eaLength);
    [DllImport("ntdll.dll")] static extern uint RtlNtStatusToDosError(int status);

    static readonly HashSet<string> ExcludedDirectories = new HashSet<string>(StringComparer.OrdinalIgnoreCase) {
        ".git", ".ssh", ".aws", ".azure", ".gnupg", ".kube", ".docker", ".config",
        ".codex", ".openclaw", ".claude", ".gemini", ".pki", ".password-store",
        "secrets", ".secrets", "credentials", ".credentials", "OpenAI-Secure-MCP-Tunnel",
        "AppData", "ProgramData", "Windows", "Program Files", "Program Files (x86)",
        "$Recycle.Bin", "System Volume Information", "Recovery",
        "node_modules", "dist", "build", "coverage", ".next", ".cache"
    };
    static readonly Regex SensitiveFiles = new Regex(
        @"^(?:\.env(?:\..+)?|id_(?:rsa|dsa|ecdsa|ed25519)(?:\.pub)?|authorized_keys|known_hosts|credentials(?:\..+)?|secrets?(?:\..+)?|auth\.json|tokens?(?:\..+)?|Cookies|Login Data|Web Data)$|\.(?:key|pem|pfx|p12|kdbx|dpapi)$",
        RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    sealed class DirectoryPin {
        public SafeFileHandle Handle; public string Identity, Path; public uint Volume;
    }
    public sealed class Receipt {
        public string schemaVersion = "stephanos.sovereign-pdf-write.v1";
        public bool ok = true, created = true, overwritten = false, atomicDocumentPublication = false;
        public bool mutationAttempted = true, retryAllowed = false;
        public string mutationState = "CREATED", stage = "POSTCONDITION", filesystem = "NTFS";
        public string sha256, targetSha256, identity, parentIdentity;
        public int bytes, pageCount, bytesRead, durationMs;
    }

    readonly List<DirectoryPin> pins = new List<DirectoryPin>();
    readonly Stopwatch clock = Stopwatch.StartNew();
    readonly byte[] approvedBytes;
    readonly string expectedHash, targetHash, leafName;
    readonly int pageCount;
    SafeFileHandle output;
    DirectoryPin parent;
    string outputCanonical;
    bool disposed, used;
    public bool MutationAttempted { get; private set; }
    public string Stage { get; private set; }
    public string Identity { get; private set; }
    public string ParentIdentity { get { return parent == null ? null : parent.Identity; } }

    static string Hash(byte[] bytes) {
        using (var sha = SHA256.Create()) return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-", "").ToLowerInvariant();
    }
    static bool ValidUtf16(string value) {
        for (int i = 0; i < value.Length; i++) {
            if (Char.IsHighSurrogate(value[i])) {
                if (++i >= value.Length || !Char.IsLowSurrogate(value[i])) return false;
            } else if (Char.IsLowSurrogate(value[i])) return false;
        }
        return true;
    }
    static bool ValidPart(string part) {
        return part != null && part.Length > 0 && part.Length <= 255 && part != "." && part != ".."
            && ValidUtf16(part) && part.TrimEnd(' ', '.') == part
            && !Regex.IsMatch(part, "[\x00-\x1f<>:\"/\\\\|?*~]")
            && !Regex.IsMatch(part, @"^(?:CON|CONIN\$|CONOUT\$|PRN|AUX|NUL|COM[1-9\u00b9\u00b2\u00b3]|LPT[1-9\u00b9\u00b2\u00b3])(?:\.|$)", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }
    static void ValidatePath(string path) {
        if (path == null || path.Length > 240 || path.Trim() != path
            || path.StartsWith("\ufeff", StringComparison.Ordinal) || path.EndsWith("\ufeff", StringComparison.Ordinal)
            || !Regex.IsMatch(path, @"^[A-Za-z]:\\[^\\]") || !path.EndsWith(".pdf", StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("SOVEREIGN_PDF_PATH_INVALID");
        string[] parts = path.Substring(3).Split('\\');
        if (parts.Length > 64) throw new InvalidOperationException("SOVEREIGN_PDF_PATH_INVALID");
        foreach (string part in parts) {
            if (!ValidPart(part)) throw new InvalidOperationException("SOVEREIGN_PDF_PATH_INVALID");
            if (ExcludedDirectories.Contains(part) || SensitiveFiles.IsMatch(part))
                throw new InvalidOperationException("SOVEREIGN_PDF_PATH_EXCLUDED");
        }
    }
    public static void ValidateRequest(string path, byte[] bytes, string sha256, int pages) {
        ValidatePath(path);
        if (bytes == null || bytes.Length < 16 || bytes.Length > MaxPdfBytes || pages < 1 || pages > MaxPages
            || sha256 == null || !Regex.IsMatch(sha256, @"\A[a-f0-9]{64}\z"))
            throw new InvalidOperationException("SOVEREIGN_PDF_REQUEST_INVALID");
        // This is a bounded generated-byte transport check, not a PDF parser or
        // a claim that arbitrary caller PDF bytes have authenticated authority.
        if (Encoding.ASCII.GetString(bytes, 0, 9) != "%PDF-1.4\n"
            || Encoding.ASCII.GetString(bytes, bytes.Length - 6, 6) != "%%EOF\n")
            throw new InvalidOperationException("SOVEREIGN_PDF_GENERATED_BYTES_INVALID");
        if (Hash(bytes) != sha256) throw new InvalidOperationException("SOVEREIGN_PDF_HASH_MISMATCH");
    }
    void Budget() {
        if (clock.ElapsedMilliseconds >= MaxRunMs) throw new InvalidOperationException("SOVEREIGN_PDF_TIME_LIMIT");
    }
    static string FileIdentity(FileInformation info) {
        return info.Volume.ToString("x8") + ":" + info.IndexHigh.ToString("x8") + info.IndexLow.ToString("x8");
    }
    static ulong Length(FileInformation info) { return ((ulong)info.SizeHigh << 32) | info.SizeLow; }
    static FileInformation Information(SafeFileHandle handle, bool directory) {
        FileInformation info;
        if (handle == null || handle.IsInvalid || !GetFileInformationByHandle(handle, out info))
            throw new Win32Exception(Marshal.GetLastWin32Error());
        if (GetFileType(handle) != 1 || (info.Attributes & (0x400u | 0x40u)) != 0
            || (((info.Attributes & 0x10) != 0) != directory))
            throw new InvalidOperationException("SOVEREIGN_PDF_REPARSE_OR_NONREGULAR");
        if (!directory && info.Links != 1) throw new InvalidOperationException("SOVEREIGN_PDF_HARD_LINK_REJECTED");
        return info;
    }
    static string FinalPath(SafeFileHandle handle) {
        var buffer = new StringBuilder(2048);
        uint count = GetFinalPathNameByHandleW(handle, buffer, (uint)buffer.Capacity, 1);
        if (count == 0 || count >= buffer.Capacity) throw new InvalidOperationException("SOVEREIGN_PDF_PATH_IDENTITY_UNPROVEN");
        return buffer.ToString();
    }
    static SafeFileHandle RelativeOpen(SafeFileHandle directory, string name, bool create, bool parentDirectory, bool allowMissing) {
        if (!ValidPart(name)) throw new InvalidOperationException("SOVEREIGN_PDF_PATH_INVALID");
        IntPtr chars = Marshal.StringToHGlobalUni(name), unicode = IntPtr.Zero;
        bool retained = false;
        try {
            var value = new UnicodeString { Length = checked((ushort)(name.Length * 2)),
                MaximumLength = checked((ushort)((name.Length + 1) * 2)), Buffer = chars };
            unicode = Marshal.AllocHGlobal(Marshal.SizeOf(typeof(UnicodeString)));
            Marshal.StructureToPtr(value, unicode, false);
            directory.DangerousAddRef(ref retained);
            var attributes = new ObjectAttributes { Length = Marshal.SizeOf(typeof(ObjectAttributes)),
                RootDirectory = directory.DangerousGetHandle(), ObjectName = unicode,
                Attributes = 0x1040 }; // OBJ_DONT_REPARSE | OBJ_CASE_INSENSITIVE.
            IntPtr raw; IoStatusBlock ios;
            uint access = create ? 0xC0100000u : parentDirectory ? Read : 0x00100080u;
            uint sharing = create ? 0u : parentDirectory ? ShareRead : 7u;
            uint kind = create ? 0x40u : parentDirectory ? 1u : 0u;
            int status = NtCreateFile(out raw, access, ref attributes, out ios, IntPtr.Zero, create ? 0x80u : 0u,
                sharing, create ? 2u : 1u, kind | 0x20u | 0x00200000u, IntPtr.Zero, 0);
            if (allowMissing && status == NameMissing) return null;
            if (status != 0) throw new Win32Exception((int)RtlNtStatusToDosError(status));
            var result = new SafeFileHandle(raw, true);
            if (result.IsInvalid || (create && ios.Information.ToUInt64() != 2)) {
                result.Dispose(); throw new InvalidOperationException("SOVEREIGN_PDF_CREATE_UNPROVEN");
            }
            return result;
        } finally {
            if (retained) directory.DangerousRelease();
            if (unicode != IntPtr.Zero) Marshal.FreeHGlobal(unicode);
            Marshal.FreeHGlobal(chars);
        }
    }
    DirectoryPin RecordDirectory(SafeFileHandle handle, string expected, uint volume) {
        try {
            FileInformation info = Information(handle, true); string canonical = FinalPath(handle);
            if (info.Volume != volume || !String.Equals(canonical, expected, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("SOVEREIGN_PDF_PATH_IDENTITY_UNPROVEN");
            var pin = new DirectoryPin { Handle = handle, Identity = FileIdentity(info), Path = canonical, Volume = volume };
            pins.Add(pin); return pin;
        } catch { handle.Dispose(); throw; }
    }
    DirectoryPin PinParent(string path) {
        Budget();
        if (GetDriveTypeW(path.Substring(0, 3)) != 3) throw new InvalidOperationException("SOVEREIGN_PDF_LOCAL_FIXED_VOLUME_REQUIRED");
        var root = CreateFileW(@"\\?\" + path.Substring(0, 3), 0x80000000, ShareRead,
            IntPtr.Zero, 3, 0x02000000 | 0x00200000, IntPtr.Zero);
        DirectoryPin current;
        try {
            FileInformation info = Information(root, true); string volumeRoot = FinalPath(root);
            if (!Regex.IsMatch(volumeRoot, @"^\\\\\?\\Volume\{[a-fA-F0-9-]+\}\\$") || GetDriveTypeW(volumeRoot) != 3)
                throw new InvalidOperationException("SOVEREIGN_PDF_LOCAL_FIXED_VOLUME_REQUIRED");
            uint serial, maximumName, flags; var filesystem = new StringBuilder(64);
            if (!GetVolumeInformationByHandleW(root, null, 0, out serial, out maximumName, out flags, filesystem, 64)
                || serial != info.Volume || filesystem.ToString() != "NTFS")
                throw new InvalidOperationException("SOVEREIGN_PDF_NTFS_REQUIRED");
            current = RecordDirectory(root, volumeRoot, info.Volume);
        } catch { root.Dispose(); throw; }
        string[] parts = path.Substring(3).Split('\\');
        for (int i = 0; i < parts.Length - 1; i++) {
            Budget();
            var next = RelativeOpen(current.Handle, parts[i], false, true, false);
            current = RecordDirectory(next, current.Path.TrimEnd('\\') + "\\" + parts[i], current.Volume);
        }
        return current;
    }
    void VerifyParents() {
        foreach (DirectoryPin pin in pins) {
            Budget(); FileInformation info = Information(pin.Handle, true);
            if (info.Volume != pin.Volume || FileIdentity(info) != pin.Identity
                || !String.Equals(FinalPath(pin.Handle), pin.Path, StringComparison.OrdinalIgnoreCase))
                throw new InvalidOperationException("SOVEREIGN_PDF_PARENT_CHANGED");
        }
    }
    FileInformation VerifyOutput() {
        Budget(); FileInformation info = Information(output, false);
        if (info.Volume != parent.Volume || FileIdentity(info) != Identity
            || !String.Equals(FinalPath(output), outputCanonical, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException("SOVEREIGN_PDF_OUTPUT_IDENTITY_UNPROVEN");
        return info;
    }

    public SovereignPdfWriteV1(string path, byte[] bytes, string sha256, int pages) {
        Stage = "PRECONDITION";
        // All output expectations are privately captured before any parent opens.
        approvedBytes = bytes == null ? null : (byte[])bytes.Clone();
        ValidateRequest(path, approvedBytes, sha256, pages);
        expectedHash = sha256; pageCount = pages;
        targetHash = Hash(new UTF8Encoding(false, true).GetBytes(path));
        leafName = path.Substring(path.LastIndexOf('\\') + 1);
        try {
            parent = PinParent(path); outputCanonical = parent.Path.TrimEnd('\\') + "\\" + leafName;
            using (var existing = RelativeOpen(parent.Handle, leafName, false, false, true)) {
                if (existing != null) throw new InvalidOperationException("SOVEREIGN_PDF_TARGET_EXISTS");
            }
            VerifyParents();
            // Constructor never creates: the caller must own this scope before
            // MutationAttempted can become true inside Write().
        } catch { Dispose(); throw; }
    }
    public Receipt Write() {
        if (disposed || used) throw new InvalidOperationException("SOVEREIGN_PDF_REQUEST_ALREADY_USED");
        used = true; VerifyParents(); Budget();
        Stage = "NATIVE_CREATE"; MutationAttempted = true;
        // FILE_CREATE is the no-overwrite guarantee, including a raced-in leaf.
        output = RelativeOpen(parent.Handle, leafName, true, false, false);
        FileInformation before = Information(output, false); Identity = FileIdentity(before);
        if (Length(VerifyOutput()) != 0) throw new InvalidOperationException("SOVEREIGN_PDF_CREATE_UNPROVEN");
        Stage = "WRITE";
        int offset = 0;
        while (offset < approvedBytes.Length) {
            Budget(); int length = Math.Min(8192, approvedBytes.Length - offset);
            byte[] buffer = new byte[length]; Buffer.BlockCopy(approvedBytes, offset, buffer, 0, length);
            uint count;
            if (!WriteFile(output, buffer, (uint)length, out count, IntPtr.Zero) || count == 0 || count > (uint)length)
                throw new InvalidOperationException("SOVEREIGN_PDF_WRITE_UNPROVEN");
            offset += (int)count;
        }
        if (!FlushFileBuffers(output)) throw new InvalidOperationException("SOVEREIGN_PDF_FLUSH_UNPROVEN");
        Stage = "POSTCONDITION";
        VerifyParents();
        if (Length(VerifyOutput()) != (ulong)approvedBytes.Length) throw new InvalidOperationException("SOVEREIGN_PDF_LENGTH_UNPROVEN");
        long position;
        if (!SetFilePointerEx(output, 0, out position, 0) || position != 0)
            throw new InvalidOperationException("SOVEREIGN_PDF_READBACK_UNPROVEN");
        int read = 0; string actualHash;
        using (var sha = SHA256.Create()) {
            byte[] buffer = new byte[8192];
            while (read < approvedBytes.Length) {
                Budget(); uint count;
                if (!ReadFile(output, buffer, (uint)Math.Min(buffer.Length, approvedBytes.Length - read), out count, IntPtr.Zero)
                    || count == 0 || count > (uint)(approvedBytes.Length - read))
                    throw new InvalidOperationException("SOVEREIGN_PDF_READBACK_UNPROVEN");
                read += (int)count; sha.TransformBlock(buffer, 0, (int)count, buffer, 0);
            }
            sha.TransformFinalBlock(new byte[0], 0, 0);
            actualHash = BitConverter.ToString(sha.Hash).Replace("-", "").ToLowerInvariant();
        }
        if (actualHash != expectedHash || Length(VerifyOutput()) != (ulong)approvedBytes.Length)
            throw new InvalidOperationException("SOVEREIGN_PDF_READBACK_UNPROVEN");
        VerifyParents(); Budget();
        // Create-only does not mean atomic whole-document publication. The
        // namespace entry exists during writing and a crash can leave it partial.
        // No deletion by pathname and no implicit retry are authorized here.
        return new Receipt { sha256 = actualHash, targetSha256 = targetHash,
            identity = Identity, parentIdentity = ParentIdentity, bytes = approvedBytes.Length,
            pageCount = pageCount, bytesRead = read, durationMs = (int)clock.ElapsedMilliseconds };
    }
    public void Dispose() {
        if (disposed) return;
        disposed = true;
        if (output != null) { output.Dispose(); output = null; }
        for (int i = pins.Count - 1; i >= 0; i--) pins[i].Handle.Dispose();
        pins.Clear();
    }
}
